/* Teaching mechanisms, not a field nitrogen-loss forecast. The only numerical
   chemistry is the NH4+/NH3 aqueous equilibrium at approximately 25 Celsius. */
(()=>{'use strict';
const steps=[
{id:'forms',title:'氮的形态',heading:'先分清“形态”，再看氮去了哪里',formula:'有机氮 / 尿素 → NH₄⁺ → NO₃⁻',type:'主要路径',points:['有机氮存在于有机质、残体等物质中，不能把它与可直接吸收的无机氮混为一谈。','尿素是另一种输入，需要先水解；植物通常主要利用铵态氮 NH₄⁺ 与硝态氮 NO₃⁻。','氮的“转化”是形态改变；离开当前土壤—根层系统，才属于本图所示的损失出口。'],detail:'以下步骤是不同条件下的过程示意，不表示同一团土壤必然按固定速度连续完成全部反应。图中粒子用于表示路径，不代表真实氮质量。'},
{id:'mineralization',title:'有机氮矿化',heading:'微生物分解，把有机氮释放为铵态氮',formula:'有机氮 → NH₄⁺',type:'矿化 / 氨化示意',points:['微生物及其酶分解含氮有机物，释放氨态氮；在多数土壤溶液条件下主要以 NH₄⁺ 存在。','适宜的温度、水分和可分解底物会影响过程；不是所有有机氮都会立即成为可用养分。','微生物也会吸收 NH₄⁺、NO₃⁻ 合成自身有机物，形成暂时的生物固持。'],detail:'矿化与微生物同化可能同时发生。这里的同化或固持不等于把空气中的 N₂ 固定为有机氮的“生物固氮”。'},
{id:'hydrolysis',title:'尿素水解',heading:'脲酶参与水解，施肥点附近环境会改变',formula:'尿素 ─脲酶、水→ NH₄⁺ / NH₃',type:'路径概括，非逐步反应式',points:['尿素溶解后，在脲酶作用下水解，形成 NH₄⁺ / NH₃ 等产物；这不是硝化。','尿素颗粒周围的 pH 可在短时间内升高，使 NH₃ 的相对比例增加。','若发生在土表，NH₃ 更易向空气逸散；混入土层增加接触、滞留与缓冲机会。'],detail:'水解需要水分。高 pH、较高温度、表面残体与空气交换等会影响风险；本图不预测某次施肥的实际损失百分比。'},
{id:'nitrification',title:'硝化',heading:'有氧条件下，铵态氮经亚硝态氮变为硝态氮',formula:'NH₄⁺ → NO₂⁻ → NO₃⁻',type:'微生物氧化 · 需要氧',points:['硝化微生物先将氨 / 铵氧化，形成 NO₂⁻，再形成 NO₃⁻。','总体反应会产生 H⁺，可对酸化有贡献；并不是“把铵直接变成气体”。','形成的 NO₃⁻ 可以被植物吸收，也更容易随后随排水迁移或在缺氧条件下被反硝化。'],detail:'总体化学计量可写为 NH₄⁺ + 2 O₂ → NO₃⁻ + 2 H⁺ + H₂O。硝化与后面反硝化的环境要求不同。'},
{id:'retention',title:'吸收与保留',heading:'NH₄⁺ 与 NO₃⁻ 的行为不同',formula:'NH₄⁺ / NO₃⁻ → 植物与微生物',type:'生物吸收与土壤吸附',points:['植物可吸收 NH₄⁺ 和 NO₃⁻，再同化为体内有机含氮物质。','带正电的 NH₄⁺ 常被带负电的土壤交换位点吸附，相对不易立刻随水移走。','NO₃⁻ 在许多土壤中较少被交换吸附，更多留在溶液中；微生物同化则可暂时保留两种无机氮。'],detail:'吸附不是永远锁住，NH₄⁺ 也可再交换、被吸收或转化；某些矿物还可能发生层间固定。本图的 NH₄⁺ 与 NO₃⁻ 对比是常见行为，不是所有土壤都完全相同。'},
{id:'volatilization',title:'氨挥发',heading:'先形成 NH₃，再从土表向空气转移',formula:'NH₄⁺ ⇌ NH₃ + H⁺；NH₃(aq) → NH₃(g)',type:'酸碱平衡 + 气体传输',points:['真正向空气逸散的是 NH₃。NH₄⁺ 不是直接飞到空中的“铵离子气体”。','施肥点 pH 升高，平衡中 NH₃ 比例增加；温度与空气交换等也影响逸散。','同样 pH 下，混入土层不改变本图的平衡计算，但增加了 NH₃ 到达大气前的滞留与缓冲机会。'],detail:'下方仅按 25°C、pKₐ≈9.25 计算水溶液中 NH₃ 占 NH₄⁺+NH₃ 的比例。田间损失还受含水率、缓冲性、风、深度、时间等影响，不能把这个比例当作挥发损失率。'},
{id:'leaching',title:'硝态氮淋洗',heading:'水先向下排出，溶解的 NO₃⁻ 才随之越过根层',formula:'NO₃⁻(溶解态) + 下渗水 → 当前根层以下',type:'迁移路径，不是化学反应',points:['雨水或灌水进入土壤后，先补充蓄水；超过储留并形成向下排水，才出现本情景的淋洗出口。','NO₃⁻ 溶于水，在许多带负电荷的土壤中较少被交换吸附，因而可随水下移。','蓝色水滴包围青色 NO₃⁻ 粒子。看它们穿过根层下界，再进入渗漏液收集器；NH₄⁺ 则相对保留在交换位点。'],detail:'淋洗不是挥发，也不是反硝化。根层以下的硝态氮不一定立即到达地下水；图中边界仅定义当前观察根层，实际迁移受根深、土壤质地、旁路流、水量与吸收等共同影响。'},
{id:'denitrification',title:'反硝化',heading:'缺氧时，部分微生物把硝酸盐还原为气体',formula:'NO₃⁻ → NO₂⁻ → NO → N₂O → N₂',type:'微生物还原 · 并非 NH₃ 挥发',points:['缺氧时，部分微生物可用 NO₃⁻ 代替 O₂ 作为电子受体，并借助有机碳等电子供体完成还原。','反应可产生 N₂O、N₂ 等气体，气态氮离开土壤；不一定每次都完全进行到 N₂。','积水或饱和易造成缺氧，但还要有可用硝酸盐、电子供体及适宜温度和时间。切换条件比较。'],detail:'这条路径的起点是 NO₃⁻，与表面 NH₄⁺/NH₃ 平衡控制的氨挥发不同；N₂O 也可由其他土壤过程产生，本图不表示其唯一来源。'},
{id:'comparison',title:'三类损失对比',heading:'都叫“氮损失”，却不是同一条路',formula:'看起点形态、出口和发生条件',type:'点击下方路径切换情景',points:['氨挥发：由 NH₄⁺/NH₃ 平衡形成 NH₃，经土表进入空气。','淋洗：溶解的 NO₃⁻ 随向下排水越过当前根层边界。','反硝化：微生物在缺氧等条件下，将 NO₃⁻ 还原为 N₂O / N₂ 等气体。'],detail:'不同微环境中可同时发生多种过程，但不能仅凭“下雨”或“有气泡”就把三条路径等同。本页每次高亮一种情景，避免把条件混画成固定的先后链。'}
];
function ammoniaFraction(pH){if(!Number.isFinite(pH)||pH<0||pH>14)throw Error('pH must lie between 0 and 14');return 1/(1+10**(9.25-pH))}
function evaluate(options={}){const pH=options.pH??8.5,incorporated=!!options.incorporated,drainage=!!options.drainage,anoxic=!!options.anoxic,carbon=options.carbon!==false,nh3Fraction=ammoniaFraction(pH);return {pH,incorporated,drainage,anoxic,carbon,nh3Fraction,visualEscape:Math.sqrt(nh3Fraction)*(incorporated?.22:1),leachingActive:drainage,denitrificationActive:anoxic&&carbon,nitrificationFavorable:!anoxic,rootBoundary:-1.9}}
function activeLoss(step,mode='volatilization'){return step===5?'volatilization':step===6?'leaching':step===7?'denitrification':step===8?mode:null}
const routes={volatilization:{start:'NH4+/NH3(aq)',transformation:'NH4+ <=> NH3 + H+',export:'NH3(g)',exit:'air'},leaching:{start:'NO3-(aq)',carrier:'drainage water',export:'NO3-(aq)',exit:'below root zone'},denitrification:{start:'NO3-',transformation:'NO3- -> NO2- -> NO -> N2O -> N2',export:['N2O(g)','N2(g)'],exit:'air'}};
window.NitrogenMechanisms={steps,ammoniaFraction,evaluate,activeLoss,routes};
})();
